import re
import sys
from datetime import date

SWISS = re.compile(r"([0-9]{1,2})\.([0-9]{1,2})\.([0-9]{4})")
ISO = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def plausible(y, m, d):
    if m < 1 or m > 12:
        return False
    if d < 1 or d > 31:
        return False
    if m == 2 and d == 29:
        return is_leap(y)
    if m in [4, 6, 9, 11] and d > 30:
        return False
    return True


def convert(text):
    m_swiss = SWISS.fullmatch(text)
    m_iso = ISO.fullmatch(text)

    if m_swiss:
        d, mo, y = map(int, m_swiss.groups())
        if plausible(y, mo, d):
            return f"{y:04d}-{mo:02d}-{d:02d}"
        return "invalid"

    if m_iso:
        y, mo, d = map(int, m_iso.groups())
        if plausible(y, mo, d):
            return f"{d:02d}.{mo:02d}.{y:04d}"
        return "invalid"

    return "invalid"


def main():
    for line in sys.stdin:
        line = line.strip()
        if line:
            print(convert(line))


if __name__ == "__main__":
    main()
